// 状态枚举中文伴随：协议值保留 ASCII（json 输出原样），table 模式经此映射展示（对齐 errors.js 映射表做法）
const STATUS_ZH = {
  active: '活跃', inactive: '停用', pending: '待审批', approved: '已通过', rejected: '已驳回',
  published: '已上架', deprecated: '已弃用', online: '在线', offline: '离线', degraded: '降级',
