        if (date && date !== true) input.date = String(date)
        if (Object.keys(input).length === 0) fail(t('至少上报一项指标：--pv= / --uv= / --dau= / --sessions= / --avg-depth= / --retention7=（可选 --date= 补录历史）'))
        const data = await call('POST', `/api/apps/${id}/metrics-report`, input)
