/**
 * connector 插件对模型/CLI/工具桥暴露的工具（defineTool → ctx.tools 三端自动同契约）。
 * 权限点与 REST 对齐；身份与组织范围一律取自执行上下文 exec.principal（入口从令牌解析注入），
 * schema 不声明 caller 星号参数与 orgId——上下文缺失即 fail-closed，杜绝自填身份与跨 org 枚举。
 */
import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from '../../platform-core/src/index.ts'
import { t as translate } from '../../platform-i18n/src/index.ts'

export const name = 'connector-tools'
export const inject = ['tools', 'connectorHub']

export function apply(ctx: Context) {
  const t = ctx.tools

  t.register(defineTool({
    name: 'connector_catalog_search',
    description: '搜索连接器目录：providers 与 actions（含 riskLevel/requiredScopes/inputSchema）。',
    permission: 'connector.catalog.read',
    parameters: {
      keyword: { type: 'string', description: '按 provider/action 关键词过滤' },
      service: { type: 'string', description: '限定 provider（service id）' },
      kind: { type: 'string', enum: ['providers', 'actions'], description: '缺省两者都返回' },
      limit: { type: 'number', description: '返回条数上限，默认 50' },
    },
    output: { type: 'object', additionalProperties: true },
    async execute(args) {
      const catalog = await ctx.connectorHub.catalog()
      if (!catalog) return { error: translate('目录尚未同步：请先执行 connector gateway health + 目录同步') }
      const keyword = (args.keyword ?? '').toLowerCase()
      const limit = Math.min(Number(args.limit ?? 50), 200)
      const matchAction = (action: { id: string; service: string; description?: string }): boolean =>
        (!args.service || action.service === args.service)
        && (!keyword || `${action.id} ${action.service} ${action.description ?? ''}`.toLowerCase().includes(keyword))
      const providers = args.kind === 'actions' ? [] : catalog.providers
        .filter((provider) => String(provider['service'] ?? '').length > 0
          && (!args.service || String(provider['service']) === args.service)
          && (!keyword || JSON.stringify(provider).toLowerCase().includes(keyword)))
        .slice(0, limit)
      const actions = args.kind === 'providers' ? [] : catalog.actions.filter(matchAction).slice(0, limit)
      return { totalProviders: providers.length, totalActions: actions.length, skippedServices: catalog.skippedServices, providers, actions }
    },
  }))

  t.register(defineTool({
    name: 'connector_connection_list',
    description: '列出连接器连接引用（org 内；含脱敏 profile——平台永不回显凭证原文）。',
    permission: 'connector.connection.read',
    parameters: {
      provider: { type: 'string', description: '按 provider 过滤' },
    },
    output: { type: 'object', additionalProperties: true },
    async execute(args, exec) {
      // org 范围由服务端从执行上下文收敛（与 REST restrictOrgScope 同一逻辑），不接受入参
      const orgScope = ctx.connectorHub.orgScopeFor(exec.principal)
      if (orgScope === null) return { total: 0, connections: [], note: translate('当前身份无组织归属，连接可见范围为空（fail-closed）') }
      const refs = ctx.connectorHub.connections().find((item) =>
        (orgScope === undefined || item.ownerOrgId === orgScope) && (!args.provider || item.provider === args.provider))
      return {
        total: refs.length,
        connections: refs.map((item) => ({
          id: item.id, alias: item.alias, provider: item.provider, authType: item.authType,
          status: item.status, ownerOrgId: item.ownerOrgId, bridge: item.bridge,
          ocConnectionId: item.ocConnectionId,
          ...(item.maskedProfile ? { maskedProfile: item.maskedProfile } : {}),
          updatedAt: item.updatedAt,
        })),
      }
    },
  }))

  t.register(defineTool({
    name: 'connector_execute',
    description: '通过连接器网关调用 SaaS action：工作级准入（受管数字员工）+ 六步链（RBAC→权限组→审批→限流→oct_ 令牌→数据面）。admin 级 action 会返回审批单。',
    permission: 'connector.invoke',
    parameters: {
      actionId: { type: 'string', required: true, description: 'action ID（如 hackernews.get_top_stories）' },
      input: { type: 'object', description: 'action 入参' },
      connection: { type: 'string', description: '指定命名连接别名（org:<orgId>:<name>）' },
      dryRun: { type: 'boolean', description: 'true 时只做授权链预演不真实调用' },
      work: {
        type: 'object',
        description: '工作授权引用索引（§10.4：仅索引透传，授权事实由服务端回查）：permitId/runId/stepKey',
        properties: {
          permitId: { type: 'string', description: '工作授权 permit ID' },
          runId: { type: 'string', description: '执行 run ID' },
          stepKey: { type: 'string', description: '业务步骤键（同键同参重投复用稳定幂等键）' },
        },
      },
    },
    output: { type: 'object', additionalProperties: true },
    async execute(args, exec) {
      // 调用方身份取自执行上下文（入口从令牌解析），缺失即 fail-closed，不再有共享身份兜底
      const work = (args.work ?? {}) as { permitId?: unknown; runId?: unknown; stepKey?: unknown }
      const workRef = {
        ...(typeof work.permitId === 'string' && work.permitId ? { permitId: work.permitId } : {}),
        ...(typeof work.runId === 'string' && work.runId ? { runId: work.runId } : {}),
        ...(typeof work.stepKey === 'string' && work.stepKey ? { stepKey: work.stepKey } : {}),
      }
      return await ctx.connectorHub.invokeAction(ctx.connectorHub.callerFromPrincipal(exec.principal), {
        actionId: args.actionId,
        input: args.input ?? {},
        ...(args.connection ? { alias: args.connection } : {}),
        ...(args.dryRun ? { dryRun: true } : {}),
        ...(Object.keys(workRef).length > 0 ? { workRef } : {}),
      })
    },
  }))

  t.register(defineTool({
    name: 'connector_perm_group_list',
    description: '列出连接器权限组（policies/subjects/rateLimitPerMin 与令牌台账状态）。',
    permission: 'connector.connection.read',
    parameters: {},
    output: { type: 'object', additionalProperties: true },
    async execute(args, exec) {
      const orgScope = ctx.connectorHub.orgScopeFor(exec.principal)
      if (orgScope === null) return { total: 0, groups: [], note: translate('当前身份无组织归属，权限组可见范围为空（fail-closed）') }
      const groups = ctx.connectorHub.permGroups().find((group) => (orgScope === undefined || group.orgId === orgScope))
      return {
        total: groups.length,
        groups: groups.map((group) => ({
          id: group.id, name: group.name, orgId: group.orgId, description: group.description,
          policies: Object.fromEntries(Object.entries(group.policies).map(([service, policy]) => [
            service,
            {
              allowedActions: policy.allowedActions, riskCap: policy.riskCap,
              connections: policy.connections ?? [],
              readOnly: Boolean(policy.constraints?.readOnly),
              denyParams: policy.constraints?.denyParams ?? [],
            },
          ])),
          subjects: group.subjects, rateLimitPerMin: group.rateLimitPerMin,
        })),
      }
    },
  }))

  t.register(defineTool({
    name: 'connector_run_list',
    description: '查看连接器网关 run 日志（runs 对账视图：runtimeTokenId 维度，只读）。',
    permission: 'connector.runs.read',
    parameters: {
      service: { type: 'string', description: '按 provider 过滤' },
      ok: { type: 'boolean', description: '按成败过滤' },
      limit: { type: 'number', description: '条数上限默认 100' },
    },
    output: { type: 'object', additionalProperties: true },
    async execute(args) {
      return await ctx.connectorHub.listRunsView({
        ...(args.service ? { service: args.service } : {}),
        ...(typeof args.ok === 'boolean' ? { ok: args.ok } : {}),
        limit: Number(args.limit ?? 100),
      })
    },
  }))
}

files.packages/plugin-console/public/js/api.js:
/** API 客户端：令牌管理 + 统一请求封装。 */

import { activeConnection, LOCAL_ID } from './connections.js'

/**
 * 部署前缀：独立形态（根路径部署）为 ''；dsh 宿主挂载形态下页面位于 /rq/ 之下，
 * 由文档地址自动推导（SPA 全程 hash 路由，document URL 恒为目录形态）。
 */
const MOUNT = new URL('.', document.baseURI).pathname.replace(/\/$/, '')

/**
 * 活动宿主连接（docs/frontend-host-switching.md）：默认本机（base = 部署前缀，同源）；
 * 配置过远程宿主并切换后，base 为远程完整地址（含其挂载前缀），API 全部改发远程——
 * BASE 在模块加载时定刻，切换连接后经整页刷新重新定刻。
 */
const CONNECTION = activeConnection(localStorage, MOUNT)

export const BASE = CONNECTION.base
export const CONNECTION_ID = CONNECTION.id
export const CONNECTION_NAME = CONNECTION.name
/** 是否连在本机宿主（本机独有语义——宿主 Cookie 直通、本机对话面入口——仅此态生效）。 */
export const IS_LOCAL_HOST = CONNECTION.id === LOCAL_ID

const TOKEN_NS = IS_LOCAL_HOST ? '' : `@${CONNECTION.id}`
const TOKEN_KEY = `heng_ops_token${TOKEN_NS}`
const REFRESH_KEY = `heng_ops_refresh${TOKEN_NS}`
const USER_KEY = `heng_ops_user${TOKEN_NS}`

/**
 * 免登演示会话（DEMO_MODE=1，2026-10-17）：内存态 profile，不落任何浏览器存储——
 * 真登录会话的存储键语义不受污染，刷新页面由 boot 链重新探测。
 * 服务端权威设计见 plugin-console/src/demo-mode.ts；此处只消费公开标记端点的回显。
 */
let demoProfile = null

export const session = {
  get token() { return localStorage.getItem(TOKEN_KEY) ?? '' },
  get refreshToken() { return localStorage.getItem(REFRESH_KEY) ?? '' },
  saveRefresh(token) { localStorage.setItem(REFRESH_KEY, token) },
  get user() {
    // 演示会话是合成身份：token 优先——一旦存在真令牌（含演示实例上真实登录），演示态即失效
    if (this.isDemo) return { displayName: demoProfile.name, roles: ['演示访客'], demo: true }
    try { return JSON.parse(localStorage.getItem(USER_KEY) ?? 'null') } catch { return null }
  },
  save(token, user) {
    localStorage.setItem(TOKEN_KEY, token)
    localStorage.setItem(USER_KEY, JSON.stringify(user))
  },
  clear() {
    localStorage.removeItem(TOKEN_KEY)
    localStorage.removeItem(REFRESH_KEY)
    localStorage.removeItem(USER_KEY)
  },
  /** 演示只读会话是否生效（真令牌存在时恒 false，登录后横幅与访客身份自动消失）。 */
  get isDemo() { return demoProfile !== null && !this.token },
  enterDemo(profile) { demoProfile = profile },
  exitDemo() { demoProfile = null },
  get permissions() {
    if (this.isDemo) return demoProfile.readonlyPermissions ?? []
    return this.user?.permissions ?? []
  },
  can(point) {
    // console.read 蕴含规则的镜像（权威判定面：platform-core rest-gate.ts IMPLIED_POINTS，
    // 两处须同步改）——真实用户持 console.login 即视为持控制台只读基线，导航不因改点消失
    if (point === 'console.read' && this.permissions.includes('console.login')) return true
    return this.permissions.includes('*') || this.permissions.includes(point)
  },
}

/**
 * 演示态探测（公开端点 /api/platform/demo，免鉴权）：远端宿主连接同样按 BASE 发。
 * 非演示态/异常一律 { demo:false }——演示能力缺失永不阻塞正常启动链。
 */
export async function demoStatus() {
  try {
    const response = await fetch(`${BASE}/api/platform/demo`)
    const payload = await response.json().catch(() => null)
    if (!response.ok || payload?.ok === false) return { demo: false }
    return payload?.data ?? { demo: false }
  } catch {
    return { demo: false }
  }
}

export class ApiError extends Error {
  constructor(code, message, status, extra) {
    super(message)
    this.code = code
    this.status = status
    this.extra = extra
  }
}

let refreshing = null

/** access token 过期时静默续期（refresh 轮转链），失败才回落登录页。 */
async function tryRefresh() {
  if (!session.refreshToken) return false
  if (!refreshing) {
    refreshing = (async () => {
      try {
        const response = await fetch(`${BASE}/api/auth/refresh`, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ refreshToken: session.refreshToken }),
        })
        const payload = await response.json().catch(() => null)
        if (!response.ok || payload?.ok === false) return false
        localStorage.setItem(TOKEN_KEY, payload.data.token)
        localStorage.setItem(REFRESH_KEY, payload.data.refreshToken)
        return true
      } catch {
        return false
      } finally {
        setTimeout(() => { refreshing = null }, 50)
      }
    })()
  }
  return refreshing
}

async function request(method, path, body, retried = false) {
  const headers = { 'content-type': 'application/json' }
  if (session.token) headers.authorization = `Bearer ${session.token}`
  const response = await fetch(`${BASE}${path}`, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  let payload = null
  try { payload = await response.json() } catch { /* non-json */ }
  if (response.status === 401 && !retried && !PUBLIC_TOKEN_PATHS.has(path) && await tryRefresh()) {
    return request(method, path, body, true)
  }
  if (!response.ok || payload?.ok === false) {
    const err = payload?.error ?? {}
    if (response.status === 401 && !path.startsWith('/api/auth/') && !location.hash.startsWith('#/oauth')) {
      session.clear()
      if (!location.hash.startsWith('#/login')) {
        // 暂存被 401 打断的目的地：登录成功后回跳（登录页消费一次），不再落在工作台让人自己找路
        try { sessionStorage.setItem('heng_ops_next', location.pathname + location.hash) } catch { /* 忽略 */ }
        location.hash = '#/login'
      }
    }
    throw new ApiError(err.code ?? 'HTTP_' + response.status, err.message ?? `请求失败（${response.status}）`, response.status, err)
  }
  return payload?.data
}

const PUBLIC_TOKEN_PATHS = new Set(['/api/auth/login', '/api/auth/refresh', '/api/auth/sso', '/api/auth/sso/authorize', '/api/auth/sso/bind', '/api/auth/sso/register', '/api/auth/client-credentials', '/api/auth/entry-ticket-session'])

/**
 * 票据免登：一次性入场票据 → 控制台会话（门户/钉钉「打开即工作台」）。
 * 票据只进请求体与内存：调用方须先从 URL 取出并立即清除参数，不得常驻地址栏或写入 localStorage。
 */
export async function entryTicketSession(ticket) {
  const response = await fetch(`${BASE}/api/auth/entry-ticket-session`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ ticket }),
  })
  let payload = null
  try { payload = await response.json() } catch { /* non-json */ }
  if (!response.ok || payload?.ok === false) {
    const err = payload?.error ?? {}
    throw new ApiError(err.code ?? 'HTTP_' + response.status, err.message ?? `票据兑换失败（${response.status}）`, response.status, err)
  }
  const result = payload.data
  session.clear()
  session.save(result.token, result.user)
  if (result.refreshToken) session.saveRefresh(result.refreshToken)
  return result.user
}

/**
 * dsh-bridge 绑定自检（WP-04/A2）：cookie 面（rq_sid，非 Bearer 通道），不在 request() 内。
 * 独立形态（无宿主）404/异常 → 返回 null，由调用方静默处理。
 * 远程宿主连接态恒返回 null：本机宿主 Cookie 换来的是本机会话，与远程数据面无关。
 */
export async function bridgeStatus() {
  if (!IS_LOCAL_HOST) return null
  let response
  try {
    response = await fetch('/dsh-bridge/status', { headers: { accept: 'application/json' } })
  } catch {
    return null
  }
  if (!response.ok) return null
  const payload = await response.json().catch(() => null)
  return payload?.data ?? null
}

/**
 * 宿主 Cookie → 平台会话直通（控制台启动会话链第三级，与部门面板 boot 同款语义）：
 * rq_sid 已绑定宿主身份时免二次登录。路径必须根绝对（不带 BASE）——
 * /dsh-bridge/* 注册在 dsh webServer 根上，挂载形态不落 /rq 之内。
 * 独立形态（无宿主）404/HTML → null，静默跳过；远程宿主连接态同理（见 bridgeStatus）。
 */
export async function exchangeBridgeSession() {
  if (!IS_LOCAL_HOST) return null
  const status = await fetch('/dsh-bridge/status', { headers: { accept: 'application/json' } })
    .then((r) => r.json()).catch(() => null)
  if (!status?.data?.bound) return null
  const payload = await fetch('/dsh-bridge/session', { method: 'POST' })
    .then((r) => r.json()).catch(() => null)
  if (!payload?.ok) return null
  const result = payload.data
  session.save(result.token, result.user)
  if (result.refreshToken) session.saveRefresh(result.refreshToken)
  return result.user
}

/** Blob 下载（skill.zip 等二进制）：统一走 BASE 与 Bearer 头，页面不得自带裸 fetch。 */
export async function downloadBlob(path) {
  const headers = {}
  if (session.token) headers.authorization = `Bearer ${session.token}`
  const response = await fetch(`${BASE}${path}`, { headers })
  if (!response.ok) throw new ApiError('HTTP_' + response.status, `下载失败（${response.status}）`, response.status)
  return response.blob()
}

/**
 * 连接页测活（docs/frontend-host-switching.md）：探测任意宿主基址的 /api/health（公开端点）。
 * 探测目标可以是「尚未切换」的连接，不能走 request()（其 PATH 恒落在活动连接上），故在 api.js
 * 内单列（console 前端零裸 fetch 不变量的豁免边界即 api.js）。
 */
export async function probeHostBase(base) {
  const started = Date.now()
  let response
  try {
    response = await fetch(`${base}/api/health`, { signal: AbortSignal.timeout(5000) })
  } catch {
    return { ok: false, message: '不可达（地址错误，或目标宿主版本较早未放行跨域）' }
  }
  const payload = await response.json().catch(() => null)
  if (!response.ok || payload?.ok === false) return { ok: false, message: `HTTP ${response.status}` }
  return { ok: true, message: `${Date.now() - started}ms` }
}

export const api = {
  get: (path) => request('GET', path),
  post: (path, body = {}) => request('POST', path, body),
  put: (path, body = {}) => request('PUT', path, body),
  patch: (path, body = {}) => request('PATCH', path, body),
  delete: (path, body) => request('DELETE', path, body),
  qs(params) {
    const search = new URLSearchParams()
    for (const [key, value] of Object.entries(params ?? {})) {
      if (value !== undefined && value !== null && value !== '') search.set(key, String(value))
    }
    const str = search.toString()
    return str ? `?${str}` : ''
  },
}

