// 可重试错误卡，与 renderShell 内既有的页面级兜底保持一致口径。
function guard(renderThunk, target) {
  Promise.resolve()
    .then(renderThunk)
    .catch((error) => {
      target.innerHTML = `
        <div class="card card-pad" style="text-align:center;padding:44px 24px">
          <div style="font-size:30px;margin-bottom:10px">🚫</div>
