            ${groups.map((g) => `
              <div class="card card-pad mb-8">
                <div class="flex"><b class="fs-13">${esc(g.name)}</b><span class="badge ${g.enabled ? 'badge-ok' : 'badge-muted'} no-dot" style="margin-left:auto">${g.enabled ? '启用' : '停用'}</span></div>
                <div class="fs-12 text-3 mt-8">${esc(rqI18n.t('链路：'))}<span class="mono">${(g.chain ?? []).map(esc).join(' → ')}</span></div>
              </div>`).join('')}` : emptyHint('暂无渠道路由引用该模型')
        } catch (error) {
          holder.innerHTML = emptyHint(rqI18n.t('渠道路由信息不可见（{msg}）', { msg: error.message }))
        }
      })()
    }
  }

  // —— 审计 ——
  async function renderAudit() {
    tabBody.innerHTML = '<div class="text-4 fs-12">加载中…</div>'
    const logs = await fetchAssetAudit(asset)
    if (!logs.length) {
      tabBody.innerHTML = emptyHint('窗口内与该资产相关的审计事件为 0（读操作不计入，噪音控制）')
      return
    }
    tabBody.innerHTML = logs.map((l) => `
      <div class="card card-pad mb-8">
        <div class="flex" style="gap:8px;align-items:center">
          <span class="mono fs-12" style="font-weight:600">${esc(l.action)}</span>
          <span class="badge ${l.result === 'ok' ? 'badge-ok' : l.result === 'denied' ? 'badge-danger' : 'badge-warn'} no-dot" style="margin-left:auto">${esc(String(l.result ?? '').toUpperCase())}</span>
        </div>
        <div class="fs-12 text-3" style="margin-top:6px">${esc(l.actorName || '系统')} · ${esc(l.resourceName || l.resourceType || '')}</div>
        ${l.detail ? `<div class="fs-11 text-4" style="margin-top:4px">${esc(String(l.detail).slice(0, 120))}</div>` : ''}
        <div class="fs-11 text-4 tnum" style="margin-top:4px">${timeAgo(l.createdAt)}</div>
      </div>`).join('')
  }

  // —— 生命周期 ——
  async function renderLifecycle() {
    tabBody.innerHTML = '<div class="text-4 fs-12">加载中…</div>'
    let detail = null
    try {
      detail = await fetchDomainDetail(asset)
    } catch { /* 无详情权限时降级为台账口径只读展示 */ }
    const order = ['draft', 'online', 'offline', 'archived']
    const normalized = asset.lifecycle === 'deprecated' ? 'offline' : (order.includes(asset.lifecycle) ? asset.lifecycle : 'draft')
    const currentIdx = order.indexOf(normalized)
    const deprecated = asset.lifecycle === 'deprecated'
    tabBody.innerHTML = `
      <div class="micro-label mb-8">生命周期状态机 · 高危变更强制 L4 审批</div>
      <div class="timeline mb-14">
        ${order.map((s, i) => `
          <div class="tl-item">
            <span class="tl-dot${i < currentIdx ? ' done' : i === currentIdx ? ' current' : ''}"></span>
            <div>
              <div class="fs-13" style="font-weight:${i === currentIdx ? 600 : 400}">${esc(rqI18n.t(LIFECYCLE_CN[s]))}${i === currentIdx ? esc(rqI18n.t('（当前）')) : ''}</div>
              ${i === currentIdx && deprecated ? `<div class="fs-11" style="color:var(--warn)">${esc(rqI18n.t('已标记弃用：存量引用将收到迁移告警'))}</div>` : ''}
            </div>
          </div>`).join('')}
      </div>
      ${detail && (detail.availableTransitions ?? []).length ? `
        <div class="card-title mb-8">${esc(rqI18n.t('可执行动作（需在{type}页执行）', { type: rqI18n.t(TYPE_LABEL[asset.type] ?? '资产') }))}</div>
        <div class="flex mb-14" style="gap:8px;flex-wrap:wrap">
          ${detail.availableTransitions.map((t) => `<span class="badge badge-muted no-dot">${esc(t.label)}</span>`).join('')}
        </div>` : ''}
      <div class="muted-box mb-14" style="display:flex;gap:8px">
        ${icon('info', 15)}<span>${esc(rqI18n.t('上线 / 下线 / 归档等状态变更由各域生命周期端点执行，高危操作强制 L4 审批单（原因必填、全程留痕、执行结果回写）。'))}</span>
      </div>
      <a class="btn btn-default" style="width:100%" href="${domainPath(asset)}">${icon('external', 13)} ${esc(rqI18n.t('前往{type}页执行生命周期动作', { type: rqI18n.t(TYPE_LABEL[asset.type] ?? '资产') }))}</a>`
  }

  tabsEl.appendChild(tabRow(
    [
      { key: 'overview', label: '概览' },
      { key: 'monitor', label: '监控' },
      { key: 'perm', label: '权限' },
      { key: 'topology', label: '拓扑' },
      { key: 'audit', label: '审计' },
      { key: 'lifecycle', label: '生命周期' },
    ],
    'overview',
    (key) => renderTab(key),
  ))
  renderTab('overview')
  return drawer
}

files.packages/plugin-console/public/js/connec:
/**
 * 宿主服务连接管理（docs/frontend-host-switching.md）：控制台默认连本机宿主，
 * 可手动配置其他宿主服务地址（如 http://192.168.0.7:7300），配置过即可一键切换，
 * 切换后整页自动刷新生效（BASE 在 api.js 模块加载时定刻，刷新是应用新连接的唯一途径）。
 *
 * 本模块保持纯函数 + 常量：所有读写经注入的 storage（localStorage 形状），
 * Node 可直接导入（selftest 经 connections.test.mjs 直测），不触碰 DOM。
 * DOM 侧（连接页 UI）在 pages/connections.js；BASE 消费方在 api.js。
 */

/** 连接清单存储键：[{ id, name, base, createdAt }]（不含内置本机连接）。 */
export const CONNECTIONS_KEY = 'heng_ops_connections'
/** 活动连接存储键：连接 id；''/缺省 = 内置本机连接。 */
export const ACTIVE_KEY = 'heng_ops_active_connection'
/** 内置本机连接 id：base 取本页部署前缀（同源），不可删除。 */
export const LOCAL_ID = 'local'

/** 地址规范化：http(s) URL、去尾斜杠、拒绝 query/hash。合法返回 { ok, base }，否则 { ok: false, error }。 */
export function normalizeBase(raw) {
  const value = String(raw ?? '').trim()
  if (!value) return { ok: false, error: '请填写宿主服务地址' }
  if (!/^https?:\/\//i.test(value)) return { ok: false, error: '地址需以 http:// 或 https:// 开头' }
  let url
  try { url = new URL(value) } catch { return { ok: false, error: '地址格式不合法' } }
  if (url.search || url.hash) return { ok: false, error: '地址不带查询参数与 # 锚点' }
  const path = url.pathname.replace(/\/+$/, '')
  return { ok: true, base: url.origin + path }
}

/** 读取连接清单（存储损坏/形态不对时回落空清单）。 */
export function loadConnections(storage) {
  try {
    const raw = storage.getItem(CONNECTIONS_KEY)
    const list = raw ? JSON.parse(raw) : []
    if (!Array.isArray(list)) return []
    return list.filter((item) => item && typeof item.id === 'string' && typeof item.base === 'string')
  } catch { return [] }
}

export function saveConnections(storage, list) {
  storage.setItem(CONNECTIONS_KEY, JSON.stringify(list))
}

export function getActiveId(storage) {
  try { return storage.getItem(ACTIVE_KEY) || '' } catch { return '' }
}

/** 切换活动连接（只写偏好不刷新；调用方负责 location.reload() 应用）。 */
export function setActiveId(storage, id) {
  if (id === LOCAL_ID) storage.removeItem(ACTIVE_KEY)
  else storage.setItem(ACTIVE_KEY, id)
}

/**
 * 活动连接决议：本机 = { id: LOCAL_ID, name: '本机宿主服务', base: mountBase }（mountBase 为
 * 本页部署前缀 '' 或 '/rq'）；远程 = 清单内对应项，清单已删则回落本机（防悬空）。
 */
export function activeConnection(storage, mountBase = '') {
  const id = getActiveId(storage)
  if (id && id !== LOCAL_ID) {
    const found = loadConnections(storage).find((item) => item.id === id)
    if (found) return found
  }
  return { id: LOCAL_ID, name: '本机宿主服务', base: mountBase }
}

/** 新增/更新连接：base 规范化失败返回 { ok:false, error }；同名远处自动去重更新。 */
export function upsertConnection(storage, { id, name, base }) {
  const normalized = normalizeBase(base)
  if (!normalized.ok) return normalized
  const list = loadConnections(storage)
  const target = { id: id || `conn-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`, name: String(name ?? '').trim() || new URL(normalized.base).host, base: normalized.base, createdAt: Date.now() }
  const index = list.findIndex((item) => item.id === target.id)
  if (index >= 0) {
    target.createdAt = list[index].createdAt
    list[index] = target
  } else {
    list.push(target)
  }
  saveConnections(storage, list)
  return { ok: true, list, connection: target }
}

/** 删除连接。返回 removedActive 表示删的是活动连接（调用方需回落本机并刷新）。 */
export function removeConnection(storage, id) {
  const list = loadConnections(storage).filter((item) => item.id !== id)
  saveConnections(storage, list)
  const removedActive = id !== LOCAL_ID && getActiveId(storage) === id
  if (removedActive) setActiveId(storage, LOCAL_ID)
  return { list, removedActive }
}

/**
 * 宿主服务连接管理纯函数自证（docs/frontend-host-switching.md 配套测试）。
 *
 * 运行方式（connections.js 零依赖纯 ESM，Node 直接加载）：
 *
 *     node packages/plugin-console/public/js/connections.test.mjs
 *
 * 覆盖面：地址规范化（协议/尾斜杠/挂载前缀/query-hash 拒绝）、清单增改删、
 * 活动连接决议（默认本机/远程/悬空回落）、删除活动连接的回落标记。
 */
import assert from 'node:assert/strict'
import { test } from 'node:test'

import {
  normalizeBase, loadConnections, saveConnections, upsertConnection, removeConnection,
  activeConnection, setActiveId, getActiveId, CONNECTIONS_KEY, ACTIVE_KEY, LOCAL_ID,
} from './connections.js'

/** localStorage 形状的内存 stub（Node 无 localStorage）。 */
function storageStub() {
  const store = new Map()
  return {
    getItem: (key) => (store.has(key) ? store.get(key) : null),
    setItem: (key, value) => store.set(key, String(value)),
    removeItem: (key) => store.delete(key),
    _store: store,
  }
}

test('normalizeBase：合法地址去尾斜杠、保留挂载前缀', () => {
  assert.deepEqual(normalizeBase('http://192.168.0.7:7300/'), { ok: true, base: 'http://192.168.0.7:7300' })
  assert.deepEqual(normalizeBase('  https://host.example:8801/rq/  '), { ok: true, base: 'https://host.example:8801/rq' })
  assert.equal(normalizeBase('http://localhost:7300').ok, true)
})

test('normalizeBase：缺协议/乱串/query/锚点/空值一律拒绝', () => {
  for (const bad of ['', '   ', '192.168.0.7:7300', 'ftp://x', 'http://h/a?x=1', 'http://h/a#frag', 'not a url']) {
    assert.equal(normalizeBase(bad).ok, false, `应拒绝：${bad}`)
  }
})

test('upsert：新增（名称留空回落主机名）、base 存前规范化', () => {
  const storage = storageStub()
  const first = upsertConnection(storage, { name: '', base: 'http://192.168.0.7:7300/' })
  assert.equal(first.ok, true)
  assert.equal(first.connection.name, '192.168.0.7:7300')
  assert.equal(first.connection.base, 'http://192.168.0.7:7300')
  assert.deepEqual(loadConnections(storage), [first.connection])
})

test('upsert：按 id 更新不新增；非法 base 返回错误且不落盘', () => {
  const storage = storageStub()
  const { connection } = upsertConnection(storage, { name: 'a', base: 'http://a:1' })
  const updated = upsertConnection(storage, { id: connection.id, name: 'b', base: 'http://b:2/rq' })
  assert.equal(updated.list.length, 1)
  assert.equal(updated.list[0].base, 'http://b:2/rq')
  const bad = upsertConnection(storage, { name: 'c', base: 'no-scheme' })
  assert.equal(bad.ok, false)
  assert.equal(loadConnections(storage).length, 1)
})

test('活动连接决议：默认本机（base=部署前缀）→ 切远程 → 悬空 id 回落本机', () => {
  const storage = storageStub()
  assert.equal(activeConnection(storage, '/rq').id, LOCAL_ID)
  assert.equal(activeConnection(storage, '/rq').base, '/rq')
  const { connection } = upsertConnection(storage, { name: '远端', base: 'http://192.168.0.7:7300' })
  setActiveId(storage, connection.id)
  assert.equal(getActiveId(storage), connection.id)
  const remote = activeConnection(storage, '/rq')
  assert.equal(remote.base, 'http://192.168.0.7:7300')
  // 悬空：活动 id 指向的连接被外部清掉 → 回落本机（不白屏）
  saveConnections(storage, [])
  assert.equal(activeConnection(storage, '/rq').id, LOCAL_ID)
})

test('setActiveId(LOCAL_ID) 清空偏好键；removeConnection 标记活动连接被删并回落', () => {
  const storage = storageStub()
  const { connection } = upsertConnection(storage, { name: 'x', base: 'http://x:1' })
  setActiveId(storage, connection.id)
  setActiveId(storage, LOCAL_ID)
  assert.equal(storage._store.has(ACTIVE_KEY), false)

  const other = upsertConnection(storage, { name: 'y', base: 'http://y:1' }).connection
  setActiveId(storage, connection.id)
  setActiveId(storage, other.id)
  const removed = removeConnection(storage, other.id)
  assert.equal(removed.removedActive, true)
  assert.equal(getActiveId(storage), '') // 已回落本机
})

test('removeConnection：删非活动连接不回落；损坏清单回落空数组', () => {
  const storage = storageStub()
  const a = upsertConnection(storage, { name: 'a', base: 'http://a:1' }).connection
  const b = upsertConnection(storage, { name: 'b', base: 'http://b:1' }).connection
  setActiveId(storage, a.id)
  const removed = removeConnection(storage, b.id)
  assert.equal(removed.removedActive, false)
  assert.equal(loadConnections(storage).length, 1)
  storage.setItem(CONNECTIONS_KEY, '{broken json')
  assert.deepEqual(loadConnections(storage), [])
  storage.setItem(CONNECTIONS_KEY, JSON.stringify(['not-an-object', 42]))
  assert.deepEqual(loadConnections(storage), [])
})

