    </div>
    <div class="card card-pad mb-14">
      <div class="card-title mb-8">${icon('plug', 14)} 接入端点（discovery）</div>
      <div class="desc-grid">
        <div class="desc-item"><span class="k">issuer（签发方）</span><span class="v mono">${esc(sso.discovery.issuer)}</span></div>
        <div class="desc-item"><span class="k">authorize（授权端点）</span><span class="v mono">${esc(sso.discovery.authorization_endpoint)}</span></div>
        <div class="desc-item"><span class="k">token（令牌端点）</span><span class="v mono">${esc(sso.discovery.token_endpoint)}</span></div>
        <div class="desc-item"><span class="k">userinfo（用户信息端点）</span><span class="v mono">${esc(sso.discovery.userinfo_endpoint)}</span></div>
      </div>
      <div class="flex mt-8" style="gap:8px">
        <button class="btn btn-default btn-sm" id="ag-sso-copy-discovery">复制 discovery 地址</button>
      </div>
      <div class="form-hint mt-8">id_token 验签公钥见 JWKS：<code class="mono">${esc(sso.discovery.issuer)}/.well-known/jwks.json</code></div>
    </div>
    ${entryCard}`
  holder.querySelector('#ag-sso-copy-id').onclick = () => void copyText(sso.clientId)
  holder.querySelector('#ag-sso-copy-discovery').onclick = () => void copyText(`${sso.discovery.issuer}/.well-known/openid-configuration`)
  const openBtn = holder.querySelector('#ag-sso-open')
  if (openBtn) openBtn.onclick = () => void openAgentEntry(agent)
  holder.querySelector('#ag-sso-save').onclick = async () => {
    const redirectUris = holder.querySelector('#ag-sso-redirects').value.split('\n').map((x) => x.trim()).filter(Boolean)
    const postLogoutUris = holder.querySelector('#ag-sso-postlogouts').value.split('\n').map((x) => x.trim()).filter(Boolean)
    try {
      await api.patch(`/api/agents/${agent.id}/sso-client`, { redirectUris, postLogoutUris, consentRequired: holder.querySelector('#ag-sso-consent').checked })
      toast(rqI18n.t('SSO 配置已保存')); refresh()
    } catch (error) { toast(error.message, 'error') }
  }
  const rotateBtn = holder.querySelector('#ag-sso-rotate')
  if (rotateBtn) rotateBtn.onclick = async () => {
    const result = await confirmDialog({
      title: '轮换 client_secret', danger: true, confirmText: '确认轮换',
      message: '旧 secret <b>立即失效</b>，界面侧需同步更新。新 secret 仅展示一次。',
    })
    if (!result) return
    try {
      const rotated = await api.post(`/api/agents/${agent.id}/sso-client/rotate`)
      showAgentSsoSecret(rotated)
    } catch (error) { toast(error.message, 'error') }
  }
  const disableBtn = holder.querySelector('#ag-sso-disable')
  if (disableBtn) disableBtn.onclick = async () => {
    const result = await confirmDialog({
      title: '禁用 SSO 客户端', requireReason: true, danger: true, confirmText: '立即禁用',
      message: '禁用后该 Agent 的登录跳转与令牌刷新立即失败（refresh 链一并吊销）。',
    })
    if (!result) return
    try {
      await api.post(`/api/agents/${agent.id}/sso-client/disable`, { reason: result.reason })
      toast(rqI18n.t('客户端已禁用')); refresh()
    } catch (error) { toast(error.message, 'error') }
  }
  const enableBtn = holder.querySelector('#ag-sso-enable')
  if (enableBtn) enableBtn.onclick = async () => {
    try {
      await api.post(`/api/agents/${agent.id}/sso-client/enable`)
      toast(rqI18n.t('客户端已启用')); refresh()
    } catch (error) { toast(error.message, 'error') }
  }
}

/** 签发弹窗（redirect_uris 必填；dsh 单入口形态建议填 <dsh地址>/auth/oidc/callback）。 */
function openAgentIssueSsoModal(agent, refresh) {
  const modal = openModal({
    title: rqI18n.t('签发 SSO 客户端：{name}', { name: agent.name }),
    body: `
      <div class="form-item">
        <label class="form-label">回调地址（redirect_uris，每行一个；https://，或 http:// 内网/本机地址）</label>
        <textarea class="form-control mono" id="ag-sso-new-redirects" rows="3" placeholder="http://192.168.0.7:3080/auth/oidc/callback"></textarea>
      </div>
      <label class="flex" style="gap:8px;font-size:13px;margin:8px 0;cursor:pointer">
        <input type="checkbox" id="ag-sso-new-public" style="accent-color:var(--brand-500)">
        <span>public 客户端（纯前端界面：免 secret、强制 PKCE、不发 refresh token）</span>
      </label>
      <div class="form-hint">clientSecret 仅签发时展示一次；丢失走「轮换 secret」，不要重复签发。</div>`,
    foot: `<button class="btn btn-default" data-cancel>取消</button><button class="btn btn-primary" id="ag-sso-new-ok">${icon('key', 13)}签发</button>`,
  })
  modal.el.querySelector('#ag-sso-new-ok').onclick = async () => {
    const redirectUris = modal.el.querySelector('#ag-sso-new-redirects').value.split('\n').map((x) => x.trim()).filter(Boolean)
    if (redirectUris.length === 0) { toast(rqI18n.t('至少填写一个回调地址'), 'error'); return }
    try {
      const created = await api.post(`/api/agents/${agent.id}/sso-client`, {
        redirectUris,
        clientType: modal.el.querySelector('#ag-sso-new-public').checked ? 'public' : 'confidential',
      })
      modal.close()
      showAgentSsoSecret(created)
      refresh()
    } catch (error) { toast(error.message, 'error') }
  }
}

/** secret 一次性展示弹窗。 */
function showAgentSsoSecret(created) {
  const modal = openModal({
    title: '客户端凭证（仅本次展示）',
    body: `
      <div class="form-hint" style="margin-bottom:10px">请立即复制保存；关闭后不再展示，丢失请走「轮换 secret」。</div>
      <div class="code-block" style="white-space:pre-wrap;word-break:break-all">client_id:     ${esc(created.clientId)}
client_secret: ${esc(created.clientSecret ?? '（public 客户端无 secret）')}</div>`,
    foot: `<button class="btn btn-default" id="ag-sso-secret-copy">${icon('copy', 13)}复制</button><button class="btn btn-primary" data-ok>我已保存</button>`,
  })
  modal.el.querySelector('#ag-sso-secret-copy').onclick = () => void copyText(`client_id: ${created.clientId}\nclient_secret: ${created.clientSecret ?? ''}`)
}

/** 审批中心（#/approvals · WE 治理域，规格 docs/internal/design-adaptation-spec-20261014.md §5.6）：
 *  左列表（风险 risk-pill + 标题 + 申请人/组织/时间 + 已决徽标）右详情（申请负载 dry-run 影响面 mono 列表
 *  + 审批时间线 tl-item + 底部操作条）。
 *  既有动作与状态流转一行不改逻辑只换壳：GET /api/approvals、GET /api/approvals/sla、
 *  POST /api/approvals/:id/decide（意见必填 / 高风险二次确认 / 终审标记）、DELETE /api/approvals/:id（仅驳回单）。
 *  组织名展示：优先 /api/iam/orgs 解析（无权限静默回落 orgId 原样，不造假）。 */
import { api, session } from '../api.js'
import { icon } from '../icons.js'
import {
  h, $, $$, esc, toast, openModal, collectForm, field, textareaField, statusBadge, timeAgo,
  emptyState, confirmDialog, sectionHead, tabRow,
} from '../ui.js'
import rqI18n from '../i18n.js'

export async function renderApprovals(content, params, ctx) {
  const data = await api.get('/api/approvals')
  let sla = null
  try { sla = await api.get('/api/approvals/sla?windowDays=30') } catch { /* SLA 看板失败不阻断列表 */ }
  let orgNames = new Map()
  try {
    const orgs = await api.get('/api/iam/orgs')
    orgNames = new Map((Array.isArray(orgs) ? orgs : (orgs?.orgs ?? [])).map((o) => [o.id, o.name]))
  } catch { /* 无 iam.org.read 权限时回落展示 orgId */ }

  const approvals = data.approvals
  const pendingCount = approvals.filter((a) => a.status === 'pending').length
  let statusFilter = 'pending'
  let activeId = params.get('focus')
    ?? (approvals.find((a) => a.status === 'pending') ?? approvals[0])?.id
    ?? null

  content.innerHTML = `
    ${sectionHead({
      label: 'APPROVAL / L4',
      title: '审批中心',
      extra: '上线 / 下线 / 下架 / 吊销强制审批单 · 有审批权限者单人通过即执行 · 执行结果回写',
    })}
    <div id="ap-tabs" style="margin-bottom:14px"></div>
    ${sla ? `
    <div class="card card-pad mb-14" style="display:flex;gap:18px;align-items:center;flex-wrap:wrap">
      <div class="card-title" style="margin:0">${icon('clock', 15)} ${esc(rqI18n.t('审批 SLA（近 {n} 天）', { n: sla.windowDays }))}</div>
      <div style="font-size:22px;font-weight:700;color:${sla.achievementRate >= 0.9 ? 'var(--ok)' : 'var(--danger)'}">${Math.round(sla.achievementRate * 1000) / 10}%</div>
      <span class="fs-12 text-3">${esc(rqI18n.t('≤2 工作日达成率 · 已决 {n} 单{over}', { n: sla.decided, over: sla.breached.length ? rqI18n.t(' · 超期 {n} 单', { n: sla.breached.length }) : '' }))}</span>
      <span class="fs-11 text-4">${esc(sla.calendarNote)}</span>
      ${sla.breached.length ? `<div class="fs-12" style="flex-basis:100%;color:var(--danger)">${esc(rqI18n.t('超期单：{items}{more}', { items: sla.breached.slice(0, 3).map((item) => `${esc(item.title)}${esc(rqI18n.t('（{n} 工作日）', { n: item.businessDays }))}`).join(rqI18n.t('、')), more: sla.breached.length > 3 ? rqI18n.t('等') : '' }))}</div>` : ''}
    </div>` : ''}
    <div class="grid-2" style="grid-template-columns:2fr 3fr;align-items:start">
      <div id="ap-list" style="display:flex;flex-direction:column;gap:8px"></div>
      <div id="ap-detail"></div>
    </div>`

  $('#ap-tabs').appendChild(tabRow([
    { key: 'pending', label: '待审批', badge: pendingCount, badgeTone: pendingCount > 0 ? 'warn' : undefined },
    { key: 'all', label: '全部', badge: approvals.length },
  ], statusFilter, (key) => { statusFilter = key; renderList() }))

  function visibleList() {
    return statusFilter === 'pending' ? approvals.filter((a) => a.status === 'pending') : approvals
  }

  function renderList() {
    const holder = $('#ap-list')
    holder.innerHTML = ''
    const list = visibleList()
    if (!list.length) {
      holder.appendChild(emptyState({
        title: statusFilter === 'pending' ? '没有待办审批' : '暂无审批记录',
        desc: 'L4 高危操作提交后将自动生成审批单',
        icon: 'checkSquare',
      }))
      return
    }
    for (const approval of list) {
      const decided = approval.status !== 'pending'
      const card = h(`
        <div class="card card-pad" data-id="${esc(approval.id)}" style="cursor:pointer;transition:border-color .15s,box-shadow .15s;${activeId === approval.id ? 'border-color:var(--brand-400);box-shadow:0 4px 16px -8px rgba(10,95,135,.4)' : ''}">
          <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px">
            <span style="font-size:13.5px;font-weight:500;line-height:1.45">${esc(approval.title)}</span>
            ${riskPill(approval.riskLevel)}
          </div>
          <div style="margin-top:6px;display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:11.5px;color:var(--text-3)">
            <span>${esc(approval.requesterName)}</span><span>·</span>
            <span>${esc(orgNames.get(approval.orgId) ?? approval.orgId ?? '—')}</span><span>·</span>
            <span class="mono">${esc(timeAgo(approval.createdAt))}</span>
            ${decided ? `<span style="margin-left:auto">${statusBadge(approval.status)}</span>` : ''}
          </div>
        </div>`)
      card.onclick = () => { activeId = approval.id; renderList(); renderDetail() }
      holder.appendChild(card)
    }
  }

  function renderDetail() {
    const holder = $('#ap-detail')
    holder.innerHTML = ''
    const approval = approvals.find((a) => a.id === activeId)
    if (!approval) {
      holder.appendChild(h(`<div class="card card-pad">${emptyStateText()}</div>`))
      return
    }
    const canDecide = session.can('approval.decide')
    const pending = approval.status === 'pending'
    const reason = pickReason(approval.payload)
    const payloadEntries = Object.entries(approval.payload ?? {})

    const detail = h(`
    <div class="card" style="overflow:hidden">
      <div style="border-bottom:1px solid var(--border);padding:16px 20px">
        <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px">
          <div style="min-width:0">
            <div style="font-size:15px;font-weight:600">${esc(approval.title)}</div>
            <div style="margin-top:4px;font-size:12px;color:var(--text-3)">
              <span class="mono">${esc(approval.id)}</span> · ${esc(kindLabel(approval.kind))}${esc(rqI18n.t(' · {name} 提交于 {time}', { name: approval.requesterName, time: timeAgo(approval.createdAt) }))}
            </div>
          </div>
          ${riskPill(approval.riskLevel)}
        </div>
        ${reason ? `<p style="margin-top:12px;background:var(--surface-2);border-radius:8px;padding:12px 14px;font-size:13px;line-height:1.65;color:var(--text-2)">${esc(reason)}</p>` : ''}
      </div>

      <div style="padding:16px 20px">
        <div class="micro-label" style="margin-bottom:8px;display:flex;align-items:center;gap:6px">${icon('terminal', 13)} dry-run 影响面预览（申请负载）</div>
        ${payloadEntries.length ? `
        <ul style="display:flex;flex-direction:column;gap:6px;list-style:none;padding:0;margin:0">
          ${payloadEntries.map(([key, value]) => `
          <li style="display:flex;align-items:flex-start;gap:8px;font-size:13px">
            <span style="margin-top:7px;width:4px;height:4px;border-radius:50%;background:var(--brand-primary);flex-shrink:0"></span>
            <span class="mono fs-12" style="line-height:1.6">${esc(key)}：${esc(typeof value === 'object' && value !== null ? JSON.stringify(value) : String(value))}</span>
          </li>`).join('')}
        </ul>
        <details style="margin-top:10px">
          <summary class="fs-12 text-4" style="cursor:pointer">查看完整申请负载（JSON）</summary>
          <div class="code-block" style="margin-top:8px;max-height:220px">${esc(JSON.stringify(approval.payload, null, 2))}</div>
        </details>` : emptyStateText('该审批单没有附带申请负载')}
      </div>

      <div style="border-top:1px solid var(--border);padding:16px 20px">
        <div class="micro-label" style="margin-bottom:12px">审批时间线</div>
        <div class="timeline">
          <div class="tl-item">
            <span class="tl-dot done"></span>
            <div style="min-width:0">
              <div style="font-size:13px">发起申请</div>
              <div class="tnum mono fs-11 text-3" style="margin-top:2px">${esc(timeAgo(approval.createdAt))} · ${esc(approval.requesterName)}</div>
            </div>
          </div>
          ${pending ? `
          <div class="tl-item">
            <span class="tl-dot current"></span>
            <div style="min-width:0">
              <div style="font-size:13px">等待审批</div>
              <div class="fs-12 text-3" style="margin-top:2px">任意具有审批权限的成员可处理（提交人与审批人可为同一账号）</div>
            </div>
          </div>` : `
          <div class="tl-item">
            <span class="tl-dot" style="${approval.status === 'rejected' ? 'background:var(--danger);color:var(--white)' : ''}">${approval.status === 'rejected' ? '✕' : ''}</span>
            <div style="min-width:0">
              <div style="font-size:13px">${decisionTitle(approval.status)}</div>
              <div class="tnum mono fs-11 text-3" style="margin-top:2px">${esc(timeAgo(approval.decidedAt))} · ${esc(approval.approverName ?? '')}</div>
              ${approval.opinion ? `<div class="fs-12-5 text-2" style="margin-top:4px;line-height:1.6">${esc(rqI18n.t('意见：{opinion}', { opinion: approval.opinion }))}</div>` : ''}
              ${approval.execution ? `<div class="fs-12 mono" style="margin-top:4px;word-break:break-all">${esc(approval.execution.error ?? approval.execution.result)}</div>` : ''}
            </div>
          </div>
          ${approval.finalReview ? `
          <div class="tl-item">
            <span class="tl-dot done"></span>
            <div style="min-width:0">
              <div style="font-size:13px">公司级终审标记（审计 action=approval.final_review）</div>
              <div class="tnum mono fs-11 text-3" style="margin-top:2px">${esc(timeAgo(approval.finalReview.at))} · ${esc(approval.finalReview.approverName)}</div>
            </div>
          </div>` : ''}`}
        </div>
      </div>

      <div style="display:flex;align-items:center;gap:10px;border-top:1px solid var(--border);background:var(--surface-2);padding:13px 20px;flex-wrap:wrap">
        ${pending && canDecide ? `
          <button class="btn btn-primary btn-sm" id="ap-approve" data-approve="${esc(approval.id)}">${icon('check', 14)} 通过并执行</button>
          <button class="btn btn-default btn-sm" id="ap-reject" data-reject="${esc(approval.id)}">${icon('x', 14)} 驳回（原因必填）</button>
          <span style="margin-left:auto;font-size:11px;color:var(--text-3)">执行期复核 · 挂单期间资源被禁用将执行失败留痕</span>` : ''}
        ${pending && !canDecide ? `
          <span class="fs-13 text-3">等待审批中——需具备审批权限（approval.decide）的成员处理</span>` : ''}
        ${!pending ? decidedCopy(approval) : ''}
        ${approval.status === 'rejected' && canDecide ? `
          <button class="btn btn-danger-ghost btn-sm" id="ap-delete" style="margin-left:auto">${icon('trash', 13)} 删除该驳回单</button>` : ''}
      </div>
    </div>`)

    const approveBtn = detail.querySelector('#ap-approve')
    if (approveBtn) approveBtn.onclick = () => openDecision(approval.id, 'approve', ctx, approval)
    const rejectBtn = detail.querySelector('#ap-reject')
    if (rejectBtn) rejectBtn.onclick = () => openDecision(approval.id, 'reject', ctx, approval)
    const deleteBtn = detail.querySelector('#ap-delete')
    if (deleteBtn) deleteBtn.onclick = () => deleteApproval(approval, ctx)
    holder.appendChild(detail)
  }

  renderList()
  renderDetail()
}

function emptyStateText(text = '请选择左侧审批单查看详情') {
  return `<div style="padding:36px 16px;text-align:center;color:var(--text-3);font-size:13px">${esc(text)}</div>`
}

/** 风险徽章（risk-pill 组件类）：high→红 / medium→琥珀 / 其余→灰（值来自服务端 riskLevel 字段）。 */
function riskPill(riskLevel) {
  const [cls, label] = riskLevel === 'high' ? ['risk-crit', '高风险']
    : riskLevel === 'medium' ? ['risk-high', '中风险']
    : ['risk-normal', '常规']
  return `<span class="risk-pill ${cls}">${esc(label)}</span>`
}

/** 申请理由：负载内常见字段（reason/comment/opinion/title）择一，缺省不渲染（不造话术）。 */
function pickReason(payload) {
  const raw = payload?.reason ?? payload?.comment ?? payload?.justification ?? null
  return typeof raw === 'string' && raw.trim() ? raw.trim() : null
}

function decisionTitle(status) {
  return { approved: '审批通过', executed: '审批通过并已执行', rejected: '已驳回', failed: '审批通过但执行失败' }[status] ?? status
}

function decidedCopy(approval) {
  if (approval.status === 'rejected') {
    return `<span style="font-size:13px;font-weight:500;color:var(--danger)">本单已驳回 · 原因已留痕，结果已回写并通知申请人</span>`
  }
  if (approval.status === 'failed') {
    return `<span style="font-size:13px;font-weight:500;color:var(--danger)">本单已通过但执行失败 · 失败原因已回写，可重新发起</span>`
  }
  return `<span style="font-size:13px;font-weight:500;color:#047857">本单已通过 · 结果已回写并通知申请人</span>`
}

/** 删除驳回审批单：仅清理已驳回单（不涉及已执行单与业务资产），服务端校验状态。——既有逻辑原样保留。 */
async function deleteApproval(approval, ctx) {
  const result = await confirmDialog({
    title: rqI18n.t('删除审批单 · {title}', { title: approval.title }), danger: true, confirmText: rqI18n.t('确认删除'),
    message: `${rqI18n.t('将删除该')}<b>${rqI18n.t('已驳回')}</b>${rqI18n.t('审批单（仅清理审批列表，不影响审计记录与业务资产），操作不可恢复。')}`,
  })
  if (!result) return
  try {
    await api.delete(`/api/approvals/${approval.id}`)
    toast(rqI18n.t('已删除驳回审批单'))
    ctx.rerender()
  } catch (error) { toast(error.message, 'error') }
}

/** 审批决策弹窗：意见必填、高风险二次确认（服务端强制）、可选公司级终审标记——既有逻辑逐字保留。 */
function openDecision(id, decision, ctx, approval) {
  const isHighRisk = approval?.riskLevel === 'high'
  const modal = openModal({
    title: decision === 'approve' ? rqI18n.t('审批通过') : rqI18n.t('驳回申请'),
    body: `
      ${decision === 'approve' ? `
        <div class="muted-box mb-14" style="display:flex;gap:8px;border-color:var(--ok-border);background:var(--ok-bg)">
          ${icon('check', 15)}<span>${rqI18n.t('通过后将')}<b>${rqI18n.t('自动执行')}</b>${rqI18n.t('对应的高危操作（执行结果会回写审批单）。')}</span>
        </div>` : ''}
      ${isHighRisk && decision === 'approve' ? `
        <div class="muted-box mb-14" style="display:flex;gap:8px;border-color:var(--danger-border);background:var(--danger-bg)">
          ${icon('alert', 15)}<span><b>${rqI18n.t('高风险审批（L1 公司级终审）')}</b>${rqI18n.t('：通过前请复核影响面；通过后将自动落公司级终审标记并写入审计。')}</span>
        </div>
        <label class="flex mb-14" style="gap:8px;align-items:flex-start;cursor:pointer">
          <input type="checkbox" id="apc-confirm" style="margin-top:3px">
          <span class="fs-12 text-2">${rqI18n.t('二次确认：我已完整复核该高风险操作的影响面与回滚方案（不勾选将无法通过，服务端强制）。')}</span>
        </label>` : ''}
      ${decision === 'approve' && !isHighRisk ? `
        <label class="flex mb-14" style="gap:8px;align-items:flex-start;cursor:pointer">
          <input type="checkbox" id="apc-final" style="margin-top:3px">
          <span class="fs-12 text-2">${rqI18n.t('同时落「公司级终审标记」（审计可追溯，非高风险默认可选）。')}</span>
        </label>` : ''}
      ${field(rqI18n.t('审批意见'), textareaField('opinion', { placeholder: decision === 'approve' ? rqI18n.t('如：已确认影响面，同意执行') : rqI18n.t('请说明驳回原因…') }), { required: true })}`,
    foot: `<button class="btn btn-default" data-cancel>${rqI18n.t('取消')}</button><button class="btn ${decision === 'approve' ? 'btn-primary' : 'btn-danger'}" data-ok>${decision === 'approve' ? rqI18n.t('确认通过') : rqI18n.t('确认驳回')}</button>`,
  })
  modal.el.querySelector('[data-cancel]').onclick = () => modal.close()
  modal.el.querySelector('[data-ok]').onclick = async (e) => {
    const btn = e.currentTarget
    const opinion = collectForm(modal.body).opinion
    if (!opinion) return toast(rqI18n.t('请填写审批意见'), 'error')
    if (isHighRisk && decision === 'approve' && !modal.body.querySelector('#apc-confirm')?.checked) {
      return toast(rqI18n.t('高风险审批需勾选二次确认（服务端强制）'), 'error')
    }
    const confirmed = isHighRisk && decision === 'approve'
    const finalReview = Boolean(modal.body.querySelector('#apc-final')?.checked)
    btn.classList.add('btn-loading')
    try {
      const result = await api.post(`/api/approvals/${id}/decide`, { decision, opinion, confirmed, finalReview })
      toast(decision === 'approve' ? rqI18n.t('审批通过，状态：{status}', { status: result.status }) : rqI18n.t('已驳回'))
      modal.close(); ctx.rerender()
    } catch (error) {
      toast(error.message, 'error')
    } finally {
      btn.classList.remove('btn-loading')
    }
  }
}

function kindLabel(kind) {
  return {
    'agent.online': 'Agent 上线', 'agent.offline': 'Agent 下线',
    'app.online': '应用发布', 'app.offline': '应用下架',
    'mcp.offline': 'MCP 下线',
  }[kind] ?? kind
}

/** AI 应用本体：列表 + 详情（指标/编排拓扑/成本穿透/生命周期）。 */
import { api, session } from '../api.js'
import rqI18n from '../i18n.js'
import { icon } from '../icons.js'
import {
  h, $, $$, esc, toast, openDrawer, openModal, confirmDialog, copyText,
  statusBadge, renderTable, collectForm, field, inputField, selectField, textareaField,
  fmtNum, fmtPct, fmtCost, fmtTime, timeAgo, emptyState, lineChart, maybeShowConceptCard,
  multiSelectField, searchableSelectField, mountSearchableSelects,
} from '../ui.js'
import { buildAppOnboardingText, openOnboardingModal } from '../onboarding.js'
import {
  dataClassLabel, riskClass, riskLabel, typeLabel, stateLabel, actionLabel,
  miniStat, renderTopologyList, barChartSafe,
} from './agents.js'

const APP_TYPE = { web: ['Web 应用', 'globe'], h5: ['H5', 'app'], miniapp: ['小程序', 'app'], desktop: ['桌面端', 'server'], api: ['API 服务', 'plug'] }

const isIconUrl = (value) => /^https?:\/\//i.test(String(value ?? '').trim())

/** 头像 / 图标渲染：http(s) 图片地址渲染为 <img> 头像，其余按 emoji 文本展示（.res-icon 同尺寸）。 */
function appIconHtml(value) {
  if (isIconUrl(value)) {
    return `<img class="res-icon" src="${esc(String(value).trim())}" alt="" referrerpolicy="no-referrer" style="object-fit:cover;background:linear-gradient(135deg,#eef6ff,#dcecff)">`
  }
  return `<div class="res-icon" style="background:linear-gradient(135deg,#eef6ff,#dcecff);font-size:21px">${esc(String(value ?? '').trim() || '✨')}</div>`
}

/** 平台授权直达：签发一次性入场票据后带 #entry_ticket 同窗口整页跳转应用
 *  （裸跳转已下线；弹窗子窗口已消灭——与应用自有 OIDC 接入互不影响，§6）。 */
async function openAppEntry(app) {
  try {
    const issued = await api.post(`/api/apps/${app.id}/entry-ticket`)
    location.assign(`${app.attrs['url']}#entry_ticket=${encodeURIComponent(issued.ticket)}`)
  } catch (error) { toast(error.message, 'error') }
}

export async function renderApps(content, params, ctx) {
  const data = await api.get('/api/apps')
  const apps = data.apps

  // 首次访问概念卡（易用性整改）
  maybeShowConceptCard(content, 'apps', {
    icon: 'app',
    title: 'AI 应用是什么？',
    subtitle: 'AI 应用 = 员工直接使用的智能应用入口（问答助手、文档助手等）。',
    points: [
      '形态多样：在 Agent 底座上扩展 Web / H5 / 小程序等访问入口。',
      '依赖可穿透：应用 → Agent → MCP/Skill 的调用链与成本一图归集。',
      '治理统一：谁能用、用了多少，走平台统一身份与审计。',
    ],
  })

  content.innerHTML = `
    <div class="page-head">
      <div>
        <div class="micro-label">AI APPS</div>
        <div class="page-title">AI 应用</div>
        <div class="page-sub">在 Agent 底座上扩展应用形态与访问入口；应用 → Agent → MCP/Skill 依赖一图穿透，成本链路可归集。</div>
      </div>
      <div class="page-actions">
        ${session.can('app.write') ? `<button class="btn btn-primary" id="app-add">${icon('plus', 14)}注册应用</button>` : ''}
      </div>
    </div>
    <div class="card-grid" id="app-cards"></div>`

  const holder = $('#app-cards')
  if (!apps.length) {
    holder.appendChild(emptyState({ title: '还没有 AI 应用', desc: '注册第一个应用，把 Agent 编排成产品', ...(session.can('app.write') ? { actionText: '注册应用', onAction: () => $('#app-add').click() } : {}), icon: 'app' }))
  }
  for (const app of apps) {
    const [typeLabel_, typeIcon] = APP_TYPE[app.attrs['appType']] ?? ['应用', 'app']
    const card = h(`
      <div class="res-card" data-id="${esc(app.id)}">
        <div class="res-card-top">
          ${appIconHtml(app.attrs['icon'])}
          <div class="grow">
            <div class="res-name">${esc(app.name)} ${statusBadge(app.status)}</div>
            <div class="res-slug">${esc(app.slug)} · ${esc(rqI18n.t(typeLabel_))}${app.attrs['publishVersion'] ? ' · ' + esc(app.attrs['publishVersion']) : ''}</div>
          </div>
        </div>
        <div class="res-desc">${esc(app.attrs['description'] ?? '')}</div>
        <div class="flex" style="gap:6px;flex-wrap:wrap">
          ${(Array.isArray(app.attrs['agentIds']) ? app.attrs['agentIds'] : []).length
            ? `<span class="badge badge-purple no-dot">${esc(rqI18n.t('编排 {n} 个 Agent', { n: app.attrs['agentIds'].length }))}</span>` : '<span class="text-4 fs-12">未编排 Agent</span>'}
          ${(app.attrs['channels'] ?? []).map((ch) => `<span class="badge badge-muted no-dot">${esc(ch)}</span>`).join('')}
        </div>
        <div class="res-foot">
          <div class="res-foot-main">
            <span class="metric">${icon('eye', 13)}PV ${fmtNum(app.metrics.pv ?? 0)}</span>
            <span class="metric">${icon('users', 13)}UV ${fmtNum(app.metrics.uv ?? 0)}</span>
            <span class="metric">${icon('users', 13)}DAU ${fmtNum(app.metrics.dau)}</span>
            <span class="metric">${icon('activity', 13)}${esc(rqI18n.t('会话 {n}', { n: fmtNum(app.metrics.sessions) }))}</span>
          </div>
          <div class="res-foot-side">
            ${app.attrs['url'] ? `<a class="btn btn-ghost btn-sm" data-entry href="javascript:void(0)">${icon('external', 13)}打开</a>` : ''}
            ${app.attrs['developerName'] ? `<span class="text-4">${esc(rqI18n.t('开发者 · {name}', { name: app.attrs['developerName'] }))}</span>` : ''}
          </div>
        </div>
      </div>`)
    const entryBtn = card.querySelector('[data-entry]')
    if (entryBtn) entryBtn.onclick = (e) => { e.stopPropagation(); void openAppEntry(app) }
    card.onclick = () => openAppDetail(app.id, ctx)
    holder.appendChild(card)
  }

  const addBtn = $('#app-add')
  if (addBtn) addBtn.onclick = () => openAppCreate(data.schema, ctx)
  if (params.get('action') === 'create' && session.can('app.write')) openAppCreate(data.schema, ctx)
  if (params.get('focus')) void openAppDetail(params.get('focus'), ctx)
}

async function openAppDetail(id, ctx) {
  const app = await api.get(`/api/apps/${id}`)
  const titleIcon = isIconUrl(app.attrs['icon'])
    ? `<img src="${esc(String(app.attrs['icon']).trim())}" alt="" referrerpolicy="no-referrer" style="width:22px;height:22px;border-radius:6px;object-fit:cover;vertical-align:-4px;margin-right:6px">`
    : esc(app.attrs['icon'] ?? '✨')
  const drawer = openDrawer({
    title: `${titleIcon} ${esc(app.name)}`,
    sub: `${app.slug} · ${app.attrs['url'] ?? rqI18n.t('未登记访问地址')}`,
    wide: true,
    body: `
      <div class="flex mb-14" style="gap:8px;flex-wrap:wrap">
        ${statusBadge(app.status)}
        <span class="badge ${riskClass(app.attrs['riskLevel'])} no-dot">${esc(rqI18n.t('风险：{level}', { level: rqI18n.t(riskLabel(app.attrs['riskLevel'])) }))}</span>
        <span class="badge badge-info no-dot">${esc(rqI18n.t('密级：{level}', { level: rqI18n.t(dataClassLabel(app.attrs['dataClass'])) }))}</span>
        ${app.attrs['developerName'] ? `<span class="badge badge-muted no-dot">${icon('user', 12)} ${esc(rqI18n.t('开发者：{name}', { name: app.attrs['developerName'] }))}</span>` : ''}
        ${(app.attrs['channels'] ?? []).map((ch) => `<span class="badge badge-muted no-dot">${esc(ch)}</span>`).join('')}
        ${app.attrs['url'] ? `<button class="btn btn-default btn-sm" id="app-open-entry">${icon('external', 13)}带平台身份打开应用</button>` : '<span class="text-4 fs-12">未登记访问地址</span>'}
      </div>

      <div class="stat-grid mb-20" style="grid-template-columns:repeat(6,1fr)">
        ${miniStat('eye', '今日 PV', fmtNum(app.metrics.pv ?? 0))}
        ${miniStat('users', '今日 UV', fmtNum(app.metrics.uv ?? 0))}
        ${miniStat('users', '今日 DAU', fmtNum(app.metrics.dau))}
        ${miniStat('activity', '累计会话', fmtNum(app.metrics.sessions))}
        ${miniStat('zap', '会话深度', rqI18n.t('{n} 轮', { n: app.metrics.avgDepth }))}
        ${miniStat('trending', '7 日留存', fmtPct(app.metrics.retention7))}
      </div>

      <div class="tabs" id="app-tabs">
        <div class="tab active" data-tab="topology">编排拓扑</div>
        <div class="tab" data-tab="metrics">应用指标</div>
        <div class="tab" data-tab="cost">成本穿透</div>
        <div class="tab" data-tab="lifecycle">生命周期</div>
        <div class="tab" data-tab="sso">${icon('key', 13)} SSO 配置${app.sso ? (app.sso.status === 'active' ? '' : ' ⚠') : ''}</div>
      </div>
      <div id="app-tab-body"></div>`,
    foot: (app.availableTransitions.map((t) => {
      const isL4 = t.action === 'online' || t.action === 'offline'
      return `<button class="btn ${isL4 ? 'btn-primary' : 'btn-default'}" data-action="${esc(t.action)}">${icon(t.action === 'online' ? 'play' : t.action === 'offline' ? 'alert' : 'chevronRight', 14)}${esc(t.label)}</button>`
    }).join('') || '<button class="btn btn-default" disabled>终态</button>')
      + `<button class="btn btn-default" id="app-onboard">${icon('book', 14)}生成接入提示词</button>`
      + `<button class="btn btn-default" id="app-edit">${icon('edit', 14)}编辑资料</button>`
      + (['draft', 'archived'].includes(app.status) ? `<button class="btn btn-danger-ghost" id="app-delete">${icon('trash', 14)}删除</button>` : ''),
  })

  const tabBody = drawer.body.querySelector('#app-tab-body')
  const openEntryBtn = drawer.body.querySelector('#app-open-entry')
  if (openEntryBtn) openEntryBtn.onclick = () => void openAppEntry(app)
  const renderTab = (tab) => {
    if (tab === 'topology') {
      tabBody.innerHTML = `
        <div class="card card-pad mb-14">
          <div class="card-title mb-14">${icon('gitBranch', 14)} 依赖拓扑（应用 → Agent → MCP/Skill）</div>
          ${topologySvg(app.topology)}
          <div class="form-hint mt-8">异常节点标红；一图穿透到底层能力，出问题可快速定位层级。</div>
        </div>
        <div class="card card-pad">
          <div class="card-title mb-8">结构化视图</div>
          ${renderTopologyList(app.topology)}
        </div>
        ${app.impact.length ? `
          <div class="card card-pad mt-14" style="border-color:var(--warn-border);background:var(--warn-bg)">
            <div class="card-title mb-8">${icon('alert', 14)} 影响面（若下架）</div>
            ${app.impact.map((i) => `<div class="fs-13" style="padding:3px 0">${esc(rqI18n.t('· {name}（{type}）', { name: i.name, type: rqI18n.t(typeLabel(i.type)) }))}</div>`).join('')}
          </div>` : ''}`
    }
    if (tab === 'metrics') {
      tabBody.innerHTML = `
        <div class="card card-pad mb-14">
          <div class="card-title mb-8">近 14 天 UV / DAU（日去重口径）</div>
          ${lineChart([app.metrics.series.map((s) => s.uv ?? 0), app.metrics.series.map((s) => s.dau)], { width: 640, height: 150, colors: ['#10b981', '#0052D9'], labels: ['UV', 'DAU'] })}
        </div>
        <div class="card card-pad mb-14">
          <div class="card-title mb-8">近 14 天 PV（页面浏览量）</div>
          ${barChartSafe(app.metrics.series.map((s) => ({ label: s.date, value: s.pv ?? 0 })), 640, 150)}
        </div>
        <div class="card card-pad">
          <div class="card-title mb-8">近 14 天会话数</div>
          ${barChartSafe(app.metrics.series.map((s) => ({ label: s.date, value: s.sessions })), 640, 150)}
        </div>`
    }
    if (tab === 'cost') {
      const total = app.cost.reduce((s, row) => s + row.costYuan, 0)
      tabBody.innerHTML = `
        <div class="flex-between mb-14">
          <div><span class="fs-12 text-3">累计成本</span><div style="font-size:22px;font-weight:700">${fmtCost(total)}</div></div>
          <span class="fs-12 text-3">应用 → Agent → MCP/模型 穿透归集</span>
        </div>
        ${app.cost.map((row) => `
          <div class="flex" style="padding:10px 0;border-bottom:1px solid var(--border)">
            <span class="badge badge-purple no-dot">Agent</span>
            <span class="fs-13 grow">${esc(row.agentName)}</span>
            <span class="fs-12 text-3" style="margin-right:14px">${esc(rqI18n.t('Token {t} · 调用 {c}', { t: fmtNum(row.llmTokens), c: fmtNum(row.toolCalls) }))}</span>
            <span style="font-weight:600">${fmtCost(row.costYuan)}</span>
          </div>`).join('') || '<span class="text-4 fs-12">暂无成本数据</span>'}`
    }
    if (tab === 'lifecycle') {
      tabBody.innerHTML = `
        <div class="timeline">
          ${app.lifecycleHistory.map((entry, index) => `
            <div class="timeline-item ${index === app.lifecycleHistory.length - 1 ? 'current' : 'ok'}">
              <div class="timeline-dot"></div>
              <div class="timeline-title">${esc(rqI18n.t('{action} → {state}', { action: entry.action === 'create' ? rqI18n.t('注册创建') : rqI18n.t(actionLabel(entry.action)), state: rqI18n.t(stateLabel(entry.to)) }))}</div>
              <div class="timeline-time">${esc(rqI18n.t('{time} · 操作人 {name}', { time: timeAgo(entry.at), name: entry.actor }))}</div>
              ${entry.note ? `<div class="timeline-body">${esc(entry.note)}</div>` : ''}
            </div>`).join('')}
        </div>`
    }
    if (tab === 'sso') renderSsoTab(tabBody, app, ctx)
  }
  drawer.body.querySelectorAll('#app-tabs .tab').forEach((el) => {
    el.onclick = () => {
      drawer.body.querySelectorAll('#app-tabs .tab').forEach((t) => t.classList.remove('active'))
      el.classList.add('active')
      renderTab(el.dataset.tab)
    }
  })
  renderTab('topology')

  for (const transition of app.availableTransitions) {
    const btn = drawer.el.querySelector(`[data-action="${transition.action}"]`)
    if (!btn) continue
    btn.onclick = async () => {
      if (transition.action === 'online' || transition.action === 'offline') {
        const isOnline = transition.action === 'online'
        const result = await confirmDialog({
          title: isOnline ? '应用发布上线（L4）' : '应用下架（L4）',
          requireReason: !isOnline,
          danger: !isOnline,
          confirmText: '提交审批',
          message: isOnline
            ? rqI18n.t('发布 <b>{name}</b> 需要另一管理员审批确认。', { name: esc(app.name) })
            : rqI18n.t('下架 <b>{name}</b> 后终端用户立即无法访问，机器凭证同步吊销。', { name: esc(app.name) }),
        })
        if (!result) return
        try {
          await api.post(`/api/apps/${app.id}/transition`, { action: transition.action, note: result.reason ?? '发布申请' })
          toast(rqI18n.t('已创建审批单')); drawer.close(); ctx.rerender()
        } catch (error) { toast(error.message, 'error') }
      } else {
        try {
          await api.post(`/api/apps/${app.id}/transition`, { action: transition.action })
          toast(rqI18n.t('状态已更新')); drawer.close(); ctx.rerender()
        } catch (error) { toast(error.message, 'error') }
      }
    }
  }

  const editBtn = drawer.el.querySelector('#app-edit')
  if (editBtn) editBtn.onclick = () => openAppEdit(app, ctx)

  const onboardBtn = drawer.el.querySelector('#app-onboard')
  if (onboardBtn) onboardBtn.onclick = () => openAppOnboardPrompt(app)

  const deleteBtn = drawer.el.querySelector('#app-delete')
  if (deleteBtn) deleteBtn.onclick = async () => {
    const result = await confirmDialog({
      title: rqI18n.t('删除应用 · {name}', { name: app.name }), requireReason: true, danger: true, confirmText: '确认删除',
      message: rqI18n.t('将永久删除 <b>{name}</b>：清除编排依赖、禁用 SSO 客户端与机器凭证，操作不可恢复；指标与审计数据保留。', { name: esc(app.name) }),
    })
    if (!result) return
    try {
      await api.delete(`/api/apps/${app.id}`)
      toast(rqI18n.t('已删除')); drawer.close(); ctx.rerender()
    } catch (error) { toast(error.message, 'error') }
  }
}

/** SSO 配置 tab：未签发 → 签发引导；已签发 → 回调管理 / 轮换 / 启停 / discovery；两态均附「平台直达」卡片。 */
function renderSsoTab(holder, app, ctx) {
  const sso = app.sso
  const enforced = (app.ssoEnforceTypes ?? []).includes(app.attrs['appType'])
  if (!sso) {
    holder.innerHTML = `
      <div class="card card-pad">
        <div class="card-title mb-8">${icon('key', 14)} 应用身份纳管（SSO）</div>
        <div class="fs-13 text-2 mb-8" style="line-height:1.9">
          签发 OIDC 客户端后，应用即可按标准协议接入平台统一身份：
          <div class="muted-box mt-8" style="font-size:12.5px">
            ① 授权码模式跳转 <code class="mono">${esc(app.sso?.discovery?.authorization_endpoint ?? '/oauth/authorize')}</code>（强制 PKCE S256）<br>
            ② <code class="mono">code</code> 换 <code class="mono">id_token / access_token</code>（Basic 或 Post 认证）<br>
            ③ <code class="mono">access_token</code> 调 <code class="mono">/oauth/userinfo</code> 取用户身份（sub / org / roles / tenant），业务权限应用内自理
          </div>
        </div>
        ${enforced ? `<div class="muted-box mb-14" style="display:flex;gap:8px;border-color:var(--warn-border);background:var(--warn-bg)">${icon('alert', 15)}<span><b>${esc(rqI18n.t('{type} 形态应用上线门禁', { type: app.attrs['appType'] }))}</b>${esc(rqI18n.t('：未完成 SSO 签发前，上线审批将被拒绝。'))}</span></div>` : ''}
        <button class="btn btn-primary" id="sso-issue">${icon('key', 14)}签发 SSO 客户端</button>
        <a class="btn btn-default" href="https://github.com/01men/ybkk-AIOS/blob/main/docs/app-sso-integration.md" target="_blank" style="margin-left:8px">接入文档</a>
