      toast(rqI18n.t('客户端已禁用')); openAppDetail(app.id, ctx)
    } catch (error) { toast(error.message, 'error') }
  }
  const enableBtn = holder.querySelector('#sso-enable')
  if (enableBtn) enableBtn.onclick = async () => {
