        ${field('回调地址 redirect_uris（每行一个）', `
          <textarea class="form-control mono" name="redirectUris" rows="2" placeholder="https://app.partner.example/cb"></textarea>`, { required: true, full: true, hint: '仅允许 https:// 或 http://localhost[:port]' })}
