            <span class="ellipsis" style="max-width:60%">${icon('bot', 11)} ${esc(issue.assigneeAgentName ?? issue.assigneeAgentId ?? '未指派')}</span>
            <span class="tnum mono">${issue.dueAt ? esc(fmtDue(issue.dueAt)) : ''}</span>
