  const tip = rqI18n.t('姓名含「{state}」字样，但账号状态仍为「正常」，可能是改名后未停用，请进入详情核实', { state: hit })
  return ` <span class="badge badge-warn no-dot" title="${esc(tip)}">${esc(rqI18n.t('名称疑似已{state}？', { state: hit }))}</span>`
}
