        </div>
        <div class="tree-children ${hasChildren(node) ? 'open' : ''}"></div>
      </div>`)
    const childrenEl = el.querySelector('.tree-children')
    for (const child of (node.children ?? [])) childrenEl.appendChild(treeNode(child))
