  const tools = policy.allowedTools === '*' ? rqI18n.t('全部工具') : rqI18n.t('{n} 个工具', { n: policy.allowedTools.length })
  return policy.constraints?.readOnly ? rqI18n.t('{tools} · 只读模式', { tools }) : tools
