  const data = await api.get('/api/nas/authz/decisions?limit=50').catch(() => ({ items: [] }))
  const table = $('#az-dec-table')
  // 异步回来时视图可能已被切走（测试容器重建/快速路由切换）：节点不在即放弃本次落表
  if (!table) return
  table.innerHTML = ''
  const items = data.items ?? []
