function readFileBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onerror = () => reject(new Error(rqI18n.t('读取本地文件失败')))
    reader.onload = () => resolve(String(reader.result).split(',')[1] ?? '')
    reader.readAsDataURL(file)
  })
}

function fmtBytes(value) {
  const n = Number(value)
  if (!Number.isFinite(n)) return '—'
  if (n >= 1 << 30) return (n / (1 << 30)).toFixed(1) + ' GB'
  if (n >= 1 << 20) return (n / (1 << 20)).toFixed(1) + ' MB'
  if (n >= 1 << 10) return (n / (1 << 10)).toFixed(1) + ' KB'
  return n + ' B'
}

function versionStatus(status) {
  const map = {
    published: 'published', approved: 'approved', rejected: 'rejected',
    pending_domain: 'pending_domain', pending_security: 'pending_security',
    scanning: 'scanning', deprecated: 'deprecated',
  }
  return map[status] ?? status
}

function miniStat(ic, label, value) {
  return `
    <div style="background:var(--surface-2);border-radius:10px;padding:12px 14px">
      <div style="color:var(--brand-500)">${icon(ic, 16)}</div>
      <div style="font-size:16px;font-weight:700;margin-top:6px">${value}</div>
      <div class="stat-sub">${esc(label)}</div>
    </div>`
}

function debounce(fn, ms) {
  let timer
  return (...args) => { clearTimeout(timer); timer = setTimeout(() => fn(...args), ms) }
}

/** 技能热力图卡片：行=skill、列=日、色深=使用次数（下载/安装计量口径）。 */
function heatCard({ days, skills, maxCell }) {
  const rows = skills.slice(0, 12)
  const cell = 15
  const gap = 3
  const labelW = 148
  const width = labelW + days.length * (cell + gap)
  const height = rows.length * (cell + gap) + 16
  const cells = rows.map((skill, r) => skill.cells.map((value, c) => {
    const opacity = value > 0 ? 0.1 + 0.9 * (value / maxCell) : 0.04
    return `<rect x="${labelW + c * (cell + gap)}" y="${r * (cell + gap)}" width="${cell}" height="${cell}" rx="3" fill="var(--brand-500)" fill-opacity="${opacity.toFixed(2)}"><title>${esc(rqI18n.t('{name} · {day} · {n} 次', { name: skill.name, day: days[c], n: value }))}</title></rect>`
  }).join('')).join('')
  const rowLabels = rows.map((skill, r) =>
    `<text x="0" y="${r * (cell + gap) + 11}" font-size="11" fill="var(--text-3)">${esc(skill.name.length > 13 ? skill.name.slice(0, 12) + '…' : skill.name)}</text>`).join('')
  const dayTicks = days.map((day, c) => c % 7 === 6
    ? `<text x="${labelW + c * (cell + gap)}" y="${height - 3}" font-size="10" fill="var(--text-4)">${esc(day.slice(5))}</text>` : '').join('')
  return `
    <div class="card">
      <div class="card-head"><span class="card-title">${icon('chart', 15)} 技能使用热力图</span><span class="card-sub">近 30 天 · 下载/安装计量（含历史流水回填）</span></div>
      <div class="card-body" style="padding-top:10px">
        <div style="overflow-x:auto">
          <svg width="${Math.max(width, 360)}" height="${height}" style="display:block">
            ${rowLabels}${cells}${dayTicks}
          </svg>
        </div>
        <div class="flex fs-11 text-4" style="justify-content:space-between;margin-top:4px">
          <span>${esc(rqI18n.t('Top {n}（按窗口使用次数）', { n: rows.length }))}</span>
          <span>${esc(rqI18n.t('色深 = 当日使用次数（峰值 {n}）', { n: maxCell }))}</span>
        </div>
      </div>
    </div>`
}

/** 用量与成本（#/usage · WE 治理域，规格 docs/internal/design-adaptation-spec-20261014.md §5.5）：
 *  tokens / 成本双维度切换 + 28 天面积趋势 + Top 资产横条 + 部门分摊表（占比条 + 环比）+ 单位 DAU 成本条 + 导出 CSV。
 *  数据源：GET /api/usage/report?days=28&dim=tokens|cost（WB 实现，真实 usage 事件聚合；空数据空态，零演示数据）。
 *  导出：以已加载的 28 天报表在前端组 CSV（BOM + a[download] Blob 下载，不开新窗）；
 *  月度口径的服务端导出仍保留在财务视图（/api/usage/report/monthly 与 /api/finops/report/monthly?format=csv）。 */
import { api } from '../api.js'
import { icon } from '../icons.js'
import {
  $, esc, toast, fmtNum, fmtCost, emptyState, sectionHead, tabRow, areaChart, hBarList,
  progressBar, emptyHint,
} from '../ui.js'
import rqI18n from '../i18n.js'

export async function renderUsage(content, params, ctx) {
  const dim = params.get('dim') === 'cost' ? 'cost' : 'tokens'
  content.innerHTML = '<div style="padding:48px;text-align:center;color:var(--text-3)">用量报表加载中…</div>'

  let report = null
  let loadError = null
  try {
    report = await api.get(`/api/usage/report?days=28&dim=${dim}`)
  } catch (error) {
    loadError = error
  }

  content.innerHTML = `
    ${sectionHead({
      label: 'USAGE REPORT / J4',
      title: '用量与成本穿透',
      extra: '部门 / 资产 / 应用效率三维聚合 · 价格簿零价快照 + 内部成本参考 · 对外不呈现金额结算语义',
      actions: `<button class="btn btn-default" id="usage-csv">${icon('download', 14)} 导出 CSV</button>`,
    })}
    <div id="usage-body"></div>`

  const body = $('#usage-body')
  if (loadError) {
    const box = document.createElement('div')
    body.appendChild(box)
    box.appendChild(emptyState({
      title: loadError.status === 403 ? '无用量报表读取权限' : '用量报表暂不可用',
      desc: loadError.status === 403
        ? '用量报表接口需要 usage.read 权限；如需查看请联系管理员开通。'
        : rqI18n.t('{msg}——/api/usage/report（28 天报表）可能尚未在当前宿主部署，可先前往财务视图查看月度口径报表。', { msg: loadError.message }),
      actionText: '重试',
      onAction: () => ctx.rerender(),
      icon: 'chart',
    }))
    bindExport(null)
    return
  }

  const series = report?.series ?? []
  const byOrg = report?.byOrg ?? []
  const topAssets = report?.topAssets ?? []
  const unitDau = report?.unitDau ?? []
  const days = report?.days ?? (series.length || 28)

  // 维度切换（tabRow）：切换后带 dim 参数重查（服务端按维度聚合占比/排行口径）
  const tabs = tabRow([
    { key: 'tokens', label: '消耗（tokens）' },
    { key: 'cost', label: '成本参考（元）' },
  ], dim, (key) => { location.hash = `#/usage?dim=${key}` })
  const tabsMount = document.createElement('div')
  tabsMount.appendChild(tabs)

  // report 各 cost 字段均为内部成本参考分（usage 事件聚合口径），展示/导出侧统一 /100 折元
  const yuan = (cents) => (Number(cents) || 0) / 100
  const values = series.map((point) => Number(dim === 'cost' ? yuan(point.cost) : point.tokens) || 0)
  const total = values.reduce((sum, value) => sum + value, 0)
  const chartHtml = areaChart({
    series: values,
    labels: series.map((point) => String(point.date ?? '').slice(5)),
    unit: dim === 'cost' ? '元 / 日' : 'tokens / 日',
    color: dim === 'cost' ? '#c2410c' : undefined,
    height: 200,
  })

  body.innerHTML = `
    <div class="grid-2 mb-20" style="grid-template-columns:2fr 1fr;align-items:stretch">
      <div class="card card-pad">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:12px">
          <div id="usage-tabs"></div>
          <span class="tnum mono fs-12 text-3">
