  check('越权拒绝已留痕（authz denied）', logsAll.data.items.some((log) => log.type === 'authz' && log.result === 'denied'))

  const logsFilter = await api('GET', '/api/audit/logs?type=invoke&result=ok&limit=5', { token: admin })
