      run(u('e_m', 'eo3'), ['/智造平台/生产部/质检线/外部/a'], 'read', { rules: rulesExp }).decision === 'deny')
    const rulesExp2 = { ...rulesExp, exceptions: [{ ...rulesExp.exceptions[0], expiresAt: '2026-09-01T00:00:00Z' }] }
