      && run(u('e_m', 'eo3'), ['/智造平台/生产部/质检线/外部/b'], 'write', { cGroupHits: ['eg_c'] }).decision === 'deny')
    const rulesCWrite = { ...baseRules, exceptions: [{ id: 'ex_cw', effect: 'allow', nasId: 'en1', path: '/智造平台/生产部/质检线/外部/b', ops: ['write'] }] }
    check('C 白名单目录写需显式 allow',
