      && run(u('e_ext', 'eo3', { accountType: 'external' }), ['/其他/a'], 'read').decision === 'deny')
    check('可疑标记账号 deny 转人工', run(u('e_bad', 'eo3', { accountType: 'suspended-review' }), [inScope], 'read').decision === 'deny')
