  const ownDelCheck = await api('POST', '/api/nas/authz/check', { token: admin, body: { nasId, userId: memberUid, paths: ['/skillhub/selftest/成员上传.bin'], op: 'delete' } })
  check('文件所有权判定（服务层）：上传者删除自有文档放行（owner.allow，优先于作用域/矩阵）',
