  const portalAppsAfter = await portalJson('/apps', { origin: portalOrigin })
  const portalApp = portalAppsAfter.body.data.find((item) => item.id === portalProbe.data.app.id)
  check('已上线应用进入 /apps（link=访问地址，tag/version/accent 契约齐全）',
