  let message = {}
  try { message = JSON.parse(await new Promise((resolve) => { let raw = ''; req.on('data', (c) => { raw += c }); req.on('end', () => resolve(raw)) })) } catch { /* ignore */ }
  const sessionHeaders = { 'mcp-session-id': `mcp-stub-session-${RUN_TAG}` }
